299:   template <typename T>
300:   inline void swapArray(T* arr, size_t count) {
301:     for (size_t i = 0; i < count; ++i) {
302:         arr[i] = swap(arr[i]);
303:     }
304:   }
305: 
306:   inline void swapArray(std::byte* arr, Type type, size_t count) {
307:     if (!arr || count == 0) { return; } // No work to do
308:     dispatchType(type, [&]<Type type>() {
309:       swapArray(reinterpret_cast<TypeTraits_t<type>*>(arr), count);
310:     });
311:   }
