182:     // Copies the values from a TIFF entry to a vector of integers.
183:     // \param ifd The IFD containing the entry.
184:     // \param tag The tag to look for.
185:     // \param defaultValue An optional default value to return if the tag is
186:     //                     not found.
187:     // \return A vector of integers containing the values from the TIFF entry.
188:     static std::vector<int> getIntVec(const TiffImage::IFD& ifd, Tag tag,
189:       std::optional<std::vector<int>> defaultValue = std::nullopt)
190:     {
191:       auto it = ifd.entries().find(tag);
192:       if (it != ifd.entries().end()) {
193:         const auto& entry = it->second;
194:         return dispatchType(entry.type(), [&, entry]<Type type>() {
195:             return makeIntVec<TypeTraits_t<type>>(entry);
196:         });
197:       }
198:       if (defaultValue.has_value()) {
199:         return defaultValue.value();
200:       }
201:       throw std::runtime_error("Tag not found: " + std::to_string(static_cast<int>(tag)));
202:     }
