210:     //         not found.
211:     static int getInt(const TiffImage::IFD& ifd, Tag tag,
212:       std::optional<int> defaultValue = std::nullopt)
213:     {
214:       std::optional<std::vector<int>> defaultValueVec;
215:       if (defaultValue.has_value()) {
216:         defaultValueVec = std::vector<int>{ defaultValue.value() };
217:       }
218:       auto v = getIntVec(ifd, tag, defaultValueVec);
219:       if (v.size() != 1) {
220:         throw std::runtime_error("Expected a single value for integer tag");
221:       }
222:       return v[0];
223:     }
