143:   // Base class for TIFF exporters
144:   class TiffExporter
145:   {
146:   protected:
147:     Image image_;
148: 
149:   public:
150:     // Destructor
151:     virtual ~TiffExporter() = default;
152: 
153:     // Accessor for the exported image
154:     const Image& image() const { return image_; }
155: 
156:     // Accessor for the exported image
157:     [[nodiscard]] Image takeImage() const { return std::move(image_); }
158: 
159:     // Callback for TiffCraft::load() function
160:     virtual void operator()(
161:       const TiffImage::Header& header,
162:       const TiffImage::IFD& ifd,
163:       TiffImage::ImageData imageData) = 0;
164: 
165:     // Copies the values from a TIFF entry to a vector of integers.
166:     template <typename T>
167:     static std::vector<int> makeIntVec(const TiffImage::IFD::Entry& entry)
168:     {
169:       std::vector<int> v(entry.count());
170:       const auto* values = reinterpret_cast<const T*>(entry.values());
171:       for (size_t i = 0; i < entry.count(); ++i) {
172:         if constexpr (is_rational_v<T>) {
173:           v[i] = static_cast<int>(values[i].numerator / values[i].denominator);
174:         }
175:         else {
176:           v[i] = static_cast<int>(values[i]);
177:         }
178:       }
179:       return v;
180:     }
181: 
182:     // Copies the values from a TIFF entry to a vector of integers.
183:     // \param ifd The IFD containing the entry.
184:     // \param tag The tag to look for.
185:     // \param defaultValue An optional default value to return if the tag is
186:     //                     not found.
187:     // \return A vector of integers containing the values from the TIFF entry.
188:     static std::vector<int> getIntVec(const TiffImage::IFD& ifd, Tag tag,
189:       std::optional<std::vector<int>> defaultValue = std::nullopt)
190:     {
191:       auto it = ifd.entries().find(tag);
192:       if (it != ifd.entries().end()) {
193:         const auto& entry = it->second;
194:         return dispatchType(entry.type(), [&, entry]<Type type>() {
195:             return makeIntVec<TypeTraits_t<type>>(entry);
196:         });
197:       }
198:       if (defaultValue.has_value()) {
199:         return defaultValue.value();
200:       }
201:       throw std::runtime_error("Tag not found: " + std::to_string(static_cast<int>(tag)));
202:     }
203: 
204:     // Gets one value from a TIFF entry as an integer.
205:     // \param ifd The IFD containing the entry.
206:     // \param tag The tag to look for.
207:     // \param defaultValue An optional default value to return if the tag is
208:     //                     not found.
209:     // \return The integer value from the TIFF entry, or the default value if
210:     //         not found.
211:     static int getInt(const TiffImage::IFD& ifd, Tag tag,
212:       std::optional<int> defaultValue = std::nullopt)
213:     {
214:       std::optional<std::vector<int>> defaultValueVec;
215:       if (defaultValue.has_value()) {
216:         defaultValueVec = std::vector<int>{ defaultValue.value() };
217:       }
218:       auto v = getIntVec(ifd, tag, defaultValueVec);
219:       if (v.size() != 1) {
220:         throw std::runtime_error("Expected a single value for integer tag");
221:       }
222:       return v[0];
223:     }
224: 
225:     template <typename Comp = std::equal_to<>>
226:     static int require(
227:       const TiffImage::IFD& ifd, Tag tag, std::optional<int> defaultValue,
228:       int requiredValue, Comp&& comp = {})
229:     {
230:       const int value = getInt(ifd, tag, defaultValue);
231:       if (!comp(value, requiredValue)) {
232:         throw FormatNotSupportedError(
233:           "Unsupported " + std::to_string(static_cast<int>(tag)) +
234:           " value: " + std::to_string(value) +
235:           ", expected: " + std::to_string(requiredValue));
236:       }
237:       return value;
238:     }
239: 
240:     template <typename Comp = std::equal_to<>>
241:     static int requireSamplesPerPixel(
242:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
243:     {
244:       return require(ifd, Tag::SamplesPerPixel, 1, requiredValue, comp);
245:     }
246: 
247:     template <typename Comp = std::equal_to<>>
248:     static int requirePhotometricInterpretation(
249:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
250:     {
251:       return require(ifd, Tag::PhotometricInterpretation, std::nullopt, requiredValue, comp);
252:     }
253: 
254:     template <typename Comp = std::equal_to<>>
255:     static int requireCompression(
256:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
257:     {
258:       return require(ifd, Tag::Compression, 1, requiredValue, comp);
259:     }
260: 
261:     template <typename Comp = std::equal_to<>>
262:     static int requireBitsPerSample(
263:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
264:     {
265:       return require(ifd, Tag::BitsPerSample, std::nullopt, requiredValue, comp);
266:     }
267: 
268:     template <typename Comp = std::equal_to<>>
269:     static std::vector<int> requireBitsPerSample(
270:       const TiffImage::IFD& ifd, const std::vector<int>& requiredValue,
271:       Comp&& comp = {})
272:     {
273:       auto bitsPerSample = getIntVec(ifd, Tag::BitsPerSample);
274:       if (!comp(bitsPerSample, requiredValue)) {
275:         throw FormatNotSupportedError("Unsupported bits per sample");
276:       }
277:       return bitsPerSample;
278:     }
279: 
280:     template <typename Comp = std::equal_to<>>
281:     static int requireFillOrder(
282:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
283:     {
284:       return require(ifd, Tag::FillOrder, 1, requiredValue, comp);
285:     }
286: 
287:     template <typename Comp = std::equal_to<>>
288:     static int requirePlanarConfiguration(
289:       const TiffImage::IFD& ifd, int requiredValue, Comp&& comp = {})
290:     {
291:       return require(ifd, Tag::PlanarConfiguration, 1, requiredValue, comp);
292:     }
293: 
294:     static int getWidth(const TiffImage::IFD& ifd)
295:     {
296:       return getInt(ifd, Tag::ImageWidth);;
297:     }
298: 
299:     static int getHeight(const TiffImage::IFD& ifd)
300:     {
301:       return getInt(ifd, Tag::ImageLength);
302:     }
303: 
304:     static std::vector<int> getBitsPerSample(const TiffImage::IFD& ifd)
305:     {
306:       if (ifd.entries().contains(Tag::BitsPerSample)) {
307:         return getIntVec(ifd, Tag::BitsPerSample);
308:       }
309:       return { 1 }; // default value if missing
310:     }
311: 
312:     static RectInfo getRectInfo(const TiffImage::IFD& ifd)
313:     {
314:       const std::vector<int> bitsPerSampleVec = getBitsPerSample(ifd);
315:       if (bitsPerSampleVec.empty()
316:         || std::any_of(bitsPerSampleVec.begin(), bitsPerSampleVec.end(),
317:           [&](int n) { return n != bitsPerSampleVec.front(); })) {
318:          throw FormatNotSupportedError("Unsupported bits per sample");
319:       }
320:       const int bitsPerSample = bitsPerSampleVec.front();
321:       const int samplesPerPixel = getInt(ifd, Tag::SamplesPerPixel, 1);
322:       const int planarConfiguration = getInt(ifd, Tag::PlanarConfiguration, 1);
323: 
324:       const int imageWidth = getWidth(ifd);
325:       const int imageHeight = getHeight(ifd);
326: 
327:       const int rowsPerStrip = getInt(ifd, Tag::RowsPerStrip, imageHeight);
328: 
329:       const int tileWidth = getInt(ifd, Tag::TileWidth, imageWidth);
330:       const int tileHeight = getInt(ifd, Tag::TileLength, rowsPerStrip);
331:       const int tileChannels = (planarConfiguration == 1 ? samplesPerPixel : 1);
332:       const int tileStride = (tileWidth * tileChannels * bitsPerSample + 7) / 8;
333: 
334:       return { tileWidth, tileHeight, tileStride, bitsPerSample };
335:     }
336: 
337:     template <typename SrcType, typename DstType, typename UnaryOp>
338:     void copyRectangles(
339:       const TiffImage::ImageData& imageData,  // source pixel data
340:       const RectInfo& rectInfo,               // source rectangle info
341:       size_t channels,                        // source image channels
342:       size_t planes,                          // source image planes
343:       bool equalsHostByteOrder,               // source data byte order
344:       UnaryOp&& op)
345:     {
346:       const int imageWidth = image_.width;
347:       const int imageHeight = image_.height;
348: 
349:       const int rectAcross = (imageWidth + (rectInfo.width - 1)) / rectInfo.width;
350:       const int rectDown = (imageHeight + (rectInfo.height - 1)) / rectInfo.height;
351:       const int rectsInPlane = rectAcross * rectDown;
352: 
353:       const int rectsInImage = rectAcross * rectDown * planes;
354:       if (rectsInImage != imageData.size()) {
355:         throw std::runtime_error("Rectangle count mismatch");
356:       }
357: 
358:       for (int plane = 0; plane < planes; ++plane) {
359:         for (int rectY = 0; rectY < rectDown; ++rectY) {
360:           for (int rectX = 0; rectX < rectAcross; ++rectX) {
361:             const auto& rectData = imageData[plane * rectsInPlane + rectY * rectAcross + rectX];
362:             auto currRectInfo = rectInfo;
363:             currRectInfo.width = std::min(rectInfo.width, imageWidth - rectX * rectInfo.width);
364:             currRectInfo.height = std::min(rectInfo.height, imageHeight - rectY * rectInfo.height);
365:             copyRectangle<SrcType, DstType, UnaryOp>(
366:               rectData,                    // source pixel data
367:               currRectInfo,                // source rectangle info
368:               channels,                    // source image channels
369:               equalsHostByteOrder,         // source data byte order
370:               plane,                       // destination plane
371:               rectX * rectInfo.width,      // destination column
372:               rectY * rectInfo.height,     // destination row
373:               std::forward<UnaryOp>(op));
374:           }
375:         }
376:       }
377:     }
378: 
379:     template <typename SrcType, typename DstType, typename UnaryOp>
380:     void copyRectangle(
381:       const std::vector<std::byte>& rectData, // source pixel data
382:       const RectInfo& rectInfo,               // source rectangle info
383:       size_t channels,                        // source image channels
384:       bool equalsHostByteOrder,               // source data byte order
385:       size_t dstPlane,                        // destination plane
386:       size_t dstX,                            // destination column
387:       size_t dstY,                            // destination row
388:       UnaryOp&& op)
389:     {
390:       constexpr size_t bitsPerSrcPixel = 8 * sizeof(SrcType);
391:       const auto* src = rectData.data();
392:       const auto* srcEnd = rectData.data() + rectData.size();
393: 
394:       size_t countAvail = 0;
395:       SrcType bitsAvail = 0;
396: 
397:       using ValueType = std::invoke_result_t<UnaryOp, DstType>;
398: 
399:       const size_t dstRowStride = image_.rowStride / sizeof(ValueType);
400:       const size_t dstColStride = image_.colStride / sizeof(ValueType);
401:       const size_t dstChanStride = image_.chanStride / sizeof(ValueType);
402:       const size_t dstPlaneStride = dstRowStride * image_.height;
403:       auto* dst = image_.dataPtr<ValueType>()
404:         + dstPlane * dstPlaneStride
405:         + dstY * dstRowStride
406:         + dstX * dstColStride;
407: 
408:       const auto* srcRow = src;
409:       auto* dstRow = dst;
410: 
411:       auto loop = [&](auto processor) {
412:         for (int row = 0; row < rectInfo.height; ++row) {
413:           if (src >= srcEnd) {
414:             // We've reached the end of the source tile
415:             throw std::runtime_error("Unexpected end of source tile");
416:           }
417:           srcRow = src;
418:           dstRow = dst;
419:           for (int col = 0; col < rectInfo.width; ++col) {
420:             auto* dstChan = dstRow;
421:             for (int chan = 0; chan < channels; ++chan) {
422:               DstType value = processor();
423:               *dstChan = std::invoke(op, value);
424:               dstChan += dstChanStride;
425:             }
426:             dstRow += dstColStride;
427:           }
428:           src += rectInfo.stride;
429:           dst += dstRowStride;
430:           // flush partial words when the row is complete
431:           if (countAvail > 0) {
432:             countAvail = 0;
433:             bitsAvail = 0;
434:           }
435:         }
436:       };
437: 
438:       auto process_word = [&]() -> DstType {
439:         DstType value = *reinterpret_cast<const SrcType*>(&(*srcRow));
440:         srcRow += sizeof(SrcType);
441:         if (!equalsHostByteOrder) {
442:           value = swap(value);
443:         }
444:         return value;
445:       };
446: 
447:       auto process_bits = [&]() -> DstType {
448:         size_t count = 0;
449:         DstType value = 0;
450:         while (count < rectInfo.bitsPerSample) {
451:           // make sure we have some bits available
452:           if (countAvail == 0) {
453:             bitsAvail = *reinterpret_cast<const SrcType*>(&(*srcRow));
454:             srcRow += sizeof(SrcType);
455:             if (!equalsHostByteOrder) {
456:               bitsAvail = swap(bitsAvail);
457:             }
458:             countAvail = bitsPerSrcPixel;
459:           }
460:           // consume available bits
461:           const size_t n = std::min(rectInfo.bitsPerSample - count, countAvail);
462:           value <<= n;
463:           value |= (bitsAvail >> (bitsPerSrcPixel - n));
464:           count += n;
465:           // update available bits
466:           countAvail -= n;
467:           bitsAvail <<= n;
468:         }
469:         assert(count == rectInfo.bitsPerSample);
470:         return value;
471:       };
472: 
473:       if (rectInfo.bitsPerSample == bitsPerSrcPixel) {
474:         // Fast path: bits per sample matches source pixel size
475:         loop(process_word);
476:       } else {
477:         // Slow path: bits per sample does not match source pixel size
478:         loop(process_bits);
479:       }
480:     }
481: 
482:     void invertColors() {
483:       uint8_t* data = image_.dataPtr<uint8_t>();
484:       for (size_t i = 0; i < image_.data.size(); ++i) {
485:         data[i] = ~data[i];
486:       }
487:     }
488:   };
