    load(input_file, std::ref(tiffExporter), loadParams);
  }
  catch (const std::exception& ex) {
    std::cerr << "Error: " << ex.what() << std::endl;
    return 1;
  }

  if (tiffExporter.image().data.empty()) {
    std::cerr << "No image data loaded." << std::endl;
    return 1;
  }

